+import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
+import { getUser, getAllUsers } from './users';
+
+// Mock fetch globally
+global.fetch = vi.fn();
+
+describe('User API Error Handling', () => {
+  beforeEach(() => {
+    vi.clearAllMocks();
+    vi.spyOn(console, 'error').mockImplementation(() => {});
+  });
+
+  afterEach(() => {
+    vi.restoreAllMocks();
+  });
+
+  describe('getUser', () => {
+    it('should return user data on successful API call', async () => {
+      const mockUser = { id: 1, name: 'John Doe', email: 'john@example.com' };
+      (global.fetch as any).mockResolvedValueOnce({
+        ok: true,
+        json: vi.fn().mockResolvedValueOnce(mockUser),
+      });
+
+      const result = await getUser(1);
+
+      expect(result.status).toBe(200);
+      expect(result.data).toEqual(mockUser);
+      expect(result.error).toBeUndefined();
+    });
+
+    it('should handle HTTP error responses with appropriate status code', async () => {
+      (global.fetch as any).mockResolvedValueOnce({
+        ok: false,
+        status: 404,
+        statusText: 'Not Found',
+      });
+
+      const result = await getUser(999);
+
+      expect(result.status).toBe(404);
+      expect(result.error).toBeDefined();
+      expect(result.data).toBeUndefined();
+      expect(console.error).toHaveBeenCalled();
+    });
+
+    it('should handle network errors with 500 status code', async () => {
+      (global.fetch as any).mockRejectedValueOnce(new Error('Network error'));
+
+      const result = await getUser(1);
+
+      expect(result.status).toBe(500);
+      expect(result.error).toBe('Internal server error');
+      expect(result.data).toBeUndefined();
+      expect(console.error).toHaveBeenCalled();
+    });
+
+    it('should handle parsing errors with 500 status code', async () => {
+      (global.fetch as any).mockResolvedValueOnce({
+        ok: true,
+        json: vi.fn().mockRejectedValueOnce(new Error('Invalid JSON')),
+      });
+
+      const result = await getUser(1);
+
+      expect(result.status).toBe(500);
+      expect(result.error).toBe('Internal server error');
+      expect(result.data).toBeUndefined();
+      expect(console.error).toHaveBeenCalled();
+    });
+  });
+
+  describe('getAllUsers', () => {
+    it('should return users array on successful API call', async () => {
+      const mockUsers = [
+        { id: 1, name: 'John Doe', email: 'john@example.com' },
+        { id: 2, name: 'Jane Smith', email: 'jane@example.com' },
+      ];
+      (global.fetch as any).mockResolvedValueOnce({
+        ok: true,
+        json: vi.fn().mockResolvedValueOnce(mockUsers),
+      });
+
+      const result = await getAllUsers();
+
+      expect(result.status).toBe(200);
+      expect(result.data).toEqual(mockUsers);
+      expect(result.error).toBeUndefined();
+    });
+
+    it('should handle HTTP error responses with appropriate status code', async () => {
+      (global.fetch as any).mockResolvedValueOnce({
+        ok: false,
+        status: 500,
+        statusText: 'Internal Server Error',
+      });
+
+      const result = await getAllUsers();
+
+      expect(result.status).toBe(500);
+      expect(result.error).toBeDefined();
+      expect(result.data).toBeUndefined();
+      expect(console.error).toHaveBeenCalled();
+    });
+
+    it('should handle network errors with 500 status code', async () => {
+      (global.fetch as any).mockRejectedValueOnce(new Error('Network error'));
+
+      const result = await getAllUsers();
+
+      expect(result.status).toBe(500);
+      expect(result.error).toBe('Internal server error');
+      expect(result.data).toBeUndefined();
+      expect(console.error).toHaveBeenCalled();
+    });
+
+    it('should handle parsing errors with 500 status code', async () => {
+      (global.fetch as any).mockResolvedValueOnce({
+        ok: true,
+        json: vi.fn().mockRejectedValueOnce(new Error('Invalid JSON')),
+      });
+
+      const result = await getAllUsers();
+
+      expect(result.status).toBe(500);
+      expect(result.error).toBe('Internal server error');
+      expect(result.data).toBeUndefined();
+      expect(console.error).toHaveBeenCalled();
+    });
+  });
+
+  describe('Error logging', () => {
+    it('should log errors to console when fetch fails', async () => {
+      (global.fetch as any).mockRejectedValueOnce(new Error('Connection timeout'));
+
+      await getUser(1);
+
+      expect(console.error).toHaveBeenCalledWith(
+        expect.stringContaining('Error fetching user')
+      );
+    });
+
+    it('should log errors to console when HTTP response is not ok', async () => {
+      (global.fetch as any).mockResolvedValueOnce({
+        ok: false,
+        status: 403,
+        statusText: 'Forbidden',
+      });
+
+      await getAllUsers();
+
+      expect(console.error).toHaveBeenCalledWith(
+        expect.stringContaining('API error')
+      );
+    });
+  });
+});
