-// TODO(smoke-add-error-handling): An API endpoint making an unguarded async call
+// API endpoint for fetching users with proper error handling
+
+interface ApiResponse<T> {
+  data?: T;
+  error?: string;
+  status: number;
+}
+
+interface User {
+  id: number;
+  name: string;
+  email: string;
+}
+
+/**
+ * Fetches a user by ID from an external API with error handling
+ */
+export async function getUser(id: number): Promise<ApiResponse<User>> {
+  try {
+    const response = await fetch(`https://api.example.com/users/${id}`);
+
+    if (!response.ok) {
+      console.error(`API error: ${response.status} ${response.statusText}`);
+      return {
+        status: response.status,
+        error: `Failed to fetch user: ${response.statusText}`,
+      };
+    }
+
+    const user = await response.json();
+    return {
+      data: user,
+      status: 200,
+    };
+  } catch (error) {
+    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
+    console.error(`Error fetching user: ${errorMessage}`);
+    return {
+      status: 500,
+      error: 'Internal server error',
+    };
+  }
+}
+
+/**
+ * Fetches all users from an external API with error handling
+ */
+export async function getAllUsers(): Promise<ApiResponse<User[]>> {
+  try {
+    const response = await fetch('https://api.example.com/users');
+
+    if (!response.ok) {
+      console.error(`API error: ${response.status} ${response.statusText}`);
+      return {
+        status: response.status,
+        error: `Failed to fetch users: ${response.statusText}`,
+      };
+    }
+
+    const users = await response.json();
+    return {
+      data: users,
+      status: 200,
+    };
+  } catch (error) {
+    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
+    console.error(`Error fetching users: ${errorMessage}`);
+    return {
+      status: 500,
+      error: 'Internal server error',
+    };
+  }
+}
